package com.example.minicommerce.shared.security;
import com.example.minicommerce.identity.domain.UserRole;import com.example.minicommerce.identity.infrastructure.UserEntity;import java.util.*;import org.springframework.security.core.*;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.userdetails.UserDetails;
public record UserPrincipal(Long id,String email,String password,UserRole role,boolean enabled)implements UserDetails{public static UserPrincipal from(UserEntity u){return new UserPrincipal(u.getId(),u.getEmail(),u.getPasswordHash(),u.getRole(),u.isEnabled());}@Override public Collection<? extends GrantedAuthority>getAuthorities(){return List.of(new SimpleGrantedAuthority("ROLE_"+role.name()));}@Override public String getUsername(){return email;}@Override public String getPassword(){return password;}@Override public boolean isAccountNonExpired(){return true;}@Override public boolean isAccountNonLocked(){return true;}@Override public boolean isCredentialsNonExpired(){return true;}@Override public boolean isEnabled(){return enabled;}}
